8	/*
9	 * Copy-first port of
10	 * node_modules/@salesforce/retail-react-app/app/components/recommended-products/index.jsx
11	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
12	 *
13	 * The differences from the base file are the TypeScript annotations below and house
14	 * formatting — no changed JSX, hook calls, prop names, or reordered `useEffect`s, and the base
15	 * file's own dead check (`recommendations.length < 1` on what is always an object) is ported
16	 * byte-identical in behaviour. The annotations: a `RecommendedProductsProps` type replacing the
17	 * `propTypes` block; a narrow local `RecommendedProduct` type for the one field read off a
18	 * recommendation-context product (reused for the `productTileProps` callback's own `product`
19	 * param below, since it is that same recommendation-context product); an explicit `boolean`
20	 * param on the one nested callback that isn't contextually typed; and inline
21	 * `{ productId?: string }` / `{ id?: string }` object-type-literal params on four
22	 * `.find`/`.some`/`.map` callbacks whose containing expression is untyped (`any`) and therefore
23	 * supplies no contextual parameter type — `noImplicitAny` flags these regardless of the `any`
24	 * receiver (confirmed against `npx tsc --noEmit`, which is why these four are annotated despite
25	 * this file's own initial plan expecting two of them not to need it). The `{ productId?: string
26	 * }` shape and inline-annotation style mirrors the existing precedent at
27	 * product-detail/index.tsx:437 and :735; the `{ id?: string }` shape matches the field the base
28	 * hook itself reads, `use-einstein.js`'s own `reco.recs?.map((rec) => rec.id)` (line 466).
29	 *
30	 * A sixth adjustment, found by lint rather than tsc: the base file destructures `formatMessage`
31	 * straight off `useIntl()`, but `@typescript-eslint/unbound-method` flags any destructured
32	 * reference to it — `formatMessage` is declared with method-shorthand syntax in
33	 * `@formatjs/intl/src/types.d.ts:64-65`, which this rule always flags regardless of whether the
34	 * real implementation needs `this`. Fix: keep the whole object (`const intl = useIntl();`) and
35	 * call `intl.formatMessage(...)` at each of its five call sites instead of destructuring — a
36	 * property-access call sidesteps the rule entirely, with zero behavioural change. Same
37	 * "toolchain requires a different access shape than the untyped base file used" reasoning as the
38	 * annotations above.
39	 *
40	 * A temporary `console.log('[overrides] recommended-products/index.tsx')` marker sits at the
41	 * top of the component body per AGENTS.md's copy-first rule, pending confirmation that the
42	 * override renders; removing it is a later step, not this one.
43	 */
44	
45	import React, { useEffect, useRef, useState } from 'react';
46	import type { ReactNode } from 'react';
47	import { useIntl } from 'react-intl';
48	import { Button } from '@salesforce/retail-react-app/app/components/shared/ui';
49	import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';
50	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
51	import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
52	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
53	import useIntersectionObserver from '@salesforce/retail-react-app/app/hooks/use-intersection-observer';
54	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
55	
56	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
57	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
58	import {
59	  API_ERROR_MESSAGE,
60	  TOAST_ACTION_VIEW_WISHLIST,
61	  TOAST_MESSAGE_ADDED_TO_WISHLIST,
62	  TOAST_MESSAGE_REMOVED_FROM_WISHLIST,
63	} from '@salesforce/retail-react-app/app/constants';
64	import { useShopperCustomersMutation } from '@salesforce/commerce-sdk-react';
65	
66	/**
67	 * The one field this file reads off a recommendation-context product. A real
68	 * commerce-sdk-isomorphic Product shape underlies it, but @salesforce/retail-react-app's
69	 * useEinstein/ProductScroller ship untyped (vendor.d.ts's wildcard), so this is narrowed
70	 * to exactly the field touched here rather than invented more broadly (AGENTS.md > Type
71	 * Definitions: hand-roll only the genuinely unexported shape actually used).
72	 */
73	type RecommendedProduct = { productId?: string };
74	
75	export type RecommendedProductsProps = {
76	  /* The title to appear above the product scroller */
77	  title?: ReactNode;
78	
79	  /* The zone to request */
80	  zone?: string;
81	
82	  /* The recommender to request */
83	  recommender?: string;
84	
85	  /* The products to use for recommendation context */
86	  products?: readonly Record<string, unknown>[];
87	
88	  /* Callback to determine if the component should fetch results */
89	  shouldFetch?: () => boolean;
90	
91	  // Index signature for the `...props` passthrough to ProductScroller (itself untyped — see
92	  // vendor.d.ts). Without it, the destructured rest types as `{}` instead of accepting arbitrary
93	  // passthrough, which is the base file's actual intent: forwarding whatever else the caller
94	  // passes.
95	  [key: string]: unknown;
96	};
97	
98	/**
99	 * A component for fetching and rendering product recommendations from the Einstein API
100	 * by a zone or a recommender name.
101	 */
102	const RecommendedProducts = ({
103	  zone,
104	  recommender,
105	  products,
106	  title,
107	  shouldFetch,
108	  ...props
109	}: RecommendedProductsProps) => {
110	  console.log('[overrides] recommended-products/index.tsx');
111	  const { isLoading, recommendations, getZoneRecommendations, getRecommendations, sendClickReco, sendViewReco } =
112	    useEinstein();
113	  const { data: customer } = useCurrentCustomer();
114	  const { customerId } = customer;
115	  const { data: wishlist } = useWishList();
116	  const dataCloud = useDataCloud();
117	
118	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
119	  const deleteCustomerProductListItem = useShopperCustomersMutation('deleteCustomerProductListItem');
120	  const toast = useToast();
121	  const navigate = useNavigation();
122	  const intl = useIntl();
123	
124	  const ref = useRef();
125	  const isOnScreen = useIntersectionObserver(ref, { useOnce: true });
126	  const [_products, setProducts] = useState(products);
127	
128	  useEffect(() => {
129	    // Check if the component should fetch results or not. This is useful
130	    // when you are still waiting on additional data, like `products`.
131	    if (typeof shouldFetch === 'function' && !shouldFetch()) {
132	      return;
133	    }
134	
135	    // Fetch either zone or recommender, but not both. If a zone and recommender
136	    // name are both provided, `zone` takes precendence.
137	    if (zone) {
138	      getZoneRecommendations(zone, _products);
139	      return;
140	    }
141	    if (recommender) {
142	      getRecommendations(recommender, _products);
143	      return;
144	    }
145	  }, [zone, recommender, _products]);
146	
147	  useEffect(() => {
148	    // This is an optimization that eliminates superfluous rerenders/fetching by
149	    // keeping a copy of the `products` array prop in state for shallow comparison.
150	    if (!Array.isArray(products)) {
151	      return;
152	    }
153	    if (products.length !== _products?.length || !products.every((val, index) => val === _products?.[index])) {
154	      setProducts(products);
155	    }
156	  }, [products]);
157	
158	  useEffect(() => {
159	    if (isOnScreen && recommendations?.recs) {
160	      sendViewReco(
161	        {
162	          recommenderName: recommendations.recommenderName,
163	          __recoUUID: recommendations.recoUUID,
164	        },
165	        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
166	      );
167	      dataCloud.sendViewRecommendations(
168	        {
169	          recommenderName: recommendations.recommenderName,
170	          __recoUUID: recommendations.recoUUID,
171	        },
172	        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
173	      );
174	    }
175	  }, [isOnScreen, recommendations]);
176	
177	  // The component should remove itself altogether if it has no recommendations
178	  // and we aren't loading any.
179	  if (!isLoading && (!recommendations || recommendations.length < 1)) {
180	    return null;
181	  }
182	
183	  // TODO: DRY this handler when intl provider is available globally
184	  const addItemToWishlist = async (product: RecommendedProduct) => {
185	    try {
186	      if (!wishlist || !customerId) {
187	        return;
188	      }
189	      await createCustomerProductListItem.mutateAsync({
190	        parameters: {
191	          listId: wishlist.id,
192	          customerId,
193	        },
194	        body: {
195	          quantity: 1,
196	          productId: product.productId,
197	          public: false,
198	          priority: 1,
199	          type: 'product',
200	        },
201	      });
202	
203	      toast({
204	        title: intl.formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
205	        status: 'success',
206	        action: (
207	          // it would be better if we could use <Button as={Link}>
208	          // but unfortunately the Link component is not compatible
209	          // with Chakra Toast, since the ToastManager is rendered via portal
210	          // and the toast doesn't have access to intl provider, which is a
211	          // requirement of the Link component.
212	          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
213	            {intl.formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
214	          </Button>
215	        ),
216	      });
217	    } catch {
218	      toast({
219	        title: intl.formatMessage(API_ERROR_MESSAGE),
220	        status: 'error',
221	      });
222	    }
223	  };
224	
225	  const removeItemFromWishlist = async (product: RecommendedProduct) => {
226	    try {
227	      const wishlistItem = wishlist?.customerProductListItems?.find(
228	        (item: { productId?: string }) => item.productId === product.productId,
229	      );
230	      if (!wishlistItem || !wishlist || !customerId) {
231	        return;
232	      }
233	      await deleteCustomerProductListItem.mutateAsync({
234	        parameters: {
235	          customerId,
236	          itemId: wishlistItem.id,
237	          listId: wishlist.id,
238	        },
239	      });
240	      toast({
241	        title: intl.formatMessage(TOAST_MESSAGE_REMOVED_FROM_WISHLIST),
242	        status: 'success',
243	        id: product.productId,
244	      });
245	    } catch {
246	      toast({
247	        title: intl.formatMessage(API_ERROR_MESSAGE),
248	        status: 'error',
249	      });
250	    }
251	  };
252	
253	  return (
254	    <ProductScroller
255	      ref={ref}
256	      title={title || recommendations?.displayMessage}
257	      products={recommendations.recs}
258	      isLoading={isLoading}
259	      productTileProps={(product: RecommendedProduct) => ({
260	        onClick: () => {
261	          sendClickReco(
262	            {
263	              recommenderName: recommendations.recommenderName,
264	              __recoUUID: recommendations.recoUUID,
265	            },
266	            product,
267	          );
268	        },
269	        enableFavourite: true,
270	        isFavourite: wishlist?.customerProductListItems?.some(
271	          (item: { productId?: string }) => item.productId === product?.productId,
272	        ),
273	        onFavouriteToggle: (toBeFavourite: boolean) => {
274	          const action = toBeFavourite ? addItemToWishlist : removeItemFromWishlist;
275	          return action(product);
276	        },
277	      })}
278	      {...props}
279	    />
280	  );
281	};
282	
283	export default RecommendedProducts;
