/*
 * Copy-first port of
 * node_modules/@salesforce/retail-react-app/app/components/recommended-products/index.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
 *
 * The differences from the base file are the TypeScript annotations below and house
 * formatting — no changed JSX, hook calls, prop names, or reordered `useEffect`s, and the base
 * file's own dead check (`recommendations.length < 1` on what is always an object) is ported
 * byte-identical in behaviour. The annotations: a `RecommendedProductsProps` type replacing the
 * `propTypes` block; a narrow local `RecommendedProduct` type for the one field read off a
 * recommendation-context product (reused for the `productTileProps` callback's own `product`
 * param below, since it is that same recommendation-context product); an explicit `boolean`
 * param on the one nested callback that isn't contextually typed; and inline
 * `{ productId?: string }` / `{ id?: string }` object-type-literal params on four
 * `.find`/`.some`/`.map` callbacks whose containing expression is untyped (`any`) and therefore
 * supplies no contextual parameter type — `noImplicitAny` flags these regardless of the `any`
 * receiver (confirmed against `npx tsc --noEmit`, which is why these four are annotated despite
 * this file's own initial plan expecting two of them not to need it). The `{ productId?: string
 * }` shape and inline-annotation style mirrors the existing precedent at
 * product-detail/index.tsx:437 and :735; the `{ id?: string }` shape matches the field the base
 * hook itself reads, `use-einstein.js`'s own `reco.recs?.map((rec) => rec.id)` (line 466).
 *
 * A sixth adjustment, found by lint rather than tsc: the base file destructures `formatMessage`
 * straight off `useIntl()`, but `@typescript-eslint/unbound-method` flags any destructured
 * reference to it — `formatMessage` is declared with method-shorthand syntax in
 * `@formatjs/intl/src/types.d.ts:64-65`, which this rule always flags regardless of whether the
 * real implementation needs `this`. Fix: keep the whole object (`const intl = useIntl();`) and
 * call `intl.formatMessage(...)` at each of its five call sites instead of destructuring — a
 * property-access call sidesteps the rule entirely, with zero behavioural change. Same
 * "toolchain requires a different access shape than the untyped base file used" reasoning as the
 * annotations above.
 *
 * A temporary `console.log('[overrides] recommended-products/index.tsx')` marker sits at the
 * top of the component body per AGENTS.md's copy-first rule, pending confirmation that the
 * override renders; removing it is a later step, not this one.
 */

import React, { useEffect, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { useIntl } from 'react-intl';
import { Button } from '@salesforce/retail-react-app/app/components/shared/ui';
import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
import useIntersectionObserver from '@salesforce/retail-react-app/app/hooks/use-intersection-observer';
import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';

import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
import {
  API_ERROR_MESSAGE,
  TOAST_ACTION_VIEW_WISHLIST,
  TOAST_MESSAGE_ADDED_TO_WISHLIST,
  TOAST_MESSAGE_REMOVED_FROM_WISHLIST,
} from '@salesforce/retail-react-app/app/constants';
import { useShopperCustomersMutation } from '@salesforce/commerce-sdk-react';

/**
 * The one field this file reads off a recommendation-context product. A real
 * commerce-sdk-isomorphic Product shape underlies it, but @salesforce/retail-react-app's
 * useEinstein/ProductScroller ship untyped (vendor.d.ts's wildcard), so this is narrowed
 * to exactly the field touched here rather than invented more broadly (AGENTS.md > Type
 * Definitions: hand-roll only the genuinely unexported shape actually used).
 */
type RecommendedProduct = { productId?: string };

export type RecommendedProductsProps = {
  /* The title to appear above the product scroller */
  title?: ReactNode;

  /* The zone to request */
  zone?: string;

  /* The recommender to request */
  recommender?: string;

  /* The products to use for recommendation context */
  products?: readonly Record<string, unknown>[];

  /* Callback to determine if the component should fetch results */
  shouldFetch?: () => boolean;

  // Index signature for the `...props` passthrough to ProductScroller (itself untyped — see
  // vendor.d.ts). Without it, the destructured rest types as `{}` instead of accepting arbitrary
  // passthrough, which is the base file's actual intent: forwarding whatever else the caller
  // passes.
  [key: string]: unknown;
};

/**
 * A component for fetching and rendering product recommendations from the Einstein API
 * by a zone or a recommender name.
 */
const RecommendedProducts = ({
  zone,
  recommender,
  products,
  title,
  shouldFetch,
  ...props
}: RecommendedProductsProps) => {
  console.log('[overrides] recommended-products/index.tsx');
  const { isLoading, recommendations, getZoneRecommendations, getRecommendations, sendClickReco, sendViewReco } =
    useEinstein();
  const { data: customer } = useCurrentCustomer();
  const { customerId } = customer;
  const { data: wishlist } = useWishList();
  const dataCloud = useDataCloud();

  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
  const deleteCustomerProductListItem = useShopperCustomersMutation('deleteCustomerProductListItem');
  const toast = useToast();
  const navigate = useNavigation();
  const intl = useIntl();

  const ref = useRef();
  const isOnScreen = useIntersectionObserver(ref, { useOnce: true });
  const [_products, setProducts] = useState(products);

  useEffect(() => {
    // Check if the component should fetch results or not. This is useful
    // when you are still waiting on additional data, like `products`.
    if (typeof shouldFetch === 'function' && !shouldFetch()) {
      return;
    }

    // Fetch either zone or recommender, but not both. If a zone and recommender
    // name are both provided, `zone` takes precendence.
    if (zone) {
      getZoneRecommendations(zone, _products);
      return;
    }
    if (recommender) {
      getRecommendations(recommender, _products);
      return;
    }
  }, [zone, recommender, _products]);

  useEffect(() => {
    // This is an optimization that eliminates superfluous rerenders/fetching by
    // keeping a copy of the `products` array prop in state for shallow comparison.
    if (!Array.isArray(products)) {
      return;
    }
    if (products.length !== _products?.length || !products.every((val, index) => val === _products?.[index])) {
      setProducts(products);
    }
  }, [products]);

  useEffect(() => {
    if (isOnScreen && recommendations?.recs) {
      sendViewReco(
        {
          recommenderName: recommendations.recommenderName,
          __recoUUID: recommendations.recoUUID,
        },
        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
      );
      dataCloud.sendViewRecommendations(
        {
          recommenderName: recommendations.recommenderName,
          __recoUUID: recommendations.recoUUID,
        },
        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
      );
    }
  }, [isOnScreen, recommendations]);

  // The component should remove itself altogether if it has no recommendations
  // and we aren't loading any.
  if (!isLoading && (!recommendations || recommendations.length < 1)) {
    return null;
  }

  // TODO: DRY this handler when intl provider is available globally
  const addItemToWishlist = async (product: RecommendedProduct) => {
    try {
      if (!wishlist || !customerId) {
        return;
      }
      await createCustomerProductListItem.mutateAsync({
        parameters: {
          listId: wishlist.id,
          customerId,
        },
        body: {
          quantity: 1,
          productId: product.productId,
          public: false,
          priority: 1,
          type: 'product',
        },
      });

      toast({
        title: intl.formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
        status: 'success',
        action: (
          // it would be better if we could use <Button as={Link}>
          // but unfortunately the Link component is not compatible
          // with Chakra Toast, since the ToastManager is rendered via portal
          // and the toast doesn't have access to intl provider, which is a
          // requirement of the Link component.
          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
            {intl.formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
          </Button>
        ),
      });
    } catch {
      toast({
        title: intl.formatMessage(API_ERROR_MESSAGE),
        status: 'error',
      });
    }
  };

  const removeItemFromWishlist = async (product: RecommendedProduct) => {
    try {
      const wishlistItem = wishlist?.customerProductListItems?.find(
        (item: { productId?: string }) => item.productId === product.productId,
      );
      if (!wishlistItem || !wishlist || !customerId) {
        return;
      }
      await deleteCustomerProductListItem.mutateAsync({
        parameters: {
          customerId,
          itemId: wishlistItem.id,
          listId: wishlist.id,
        },
      });
      toast({
        title: intl.formatMessage(TOAST_MESSAGE_REMOVED_FROM_WISHLIST),
        status: 'success',
        id: product.productId,
      });
    } catch {
      toast({
        title: intl.formatMessage(API_ERROR_MESSAGE),
        status: 'error',
      });
    }
  };

  return (
    <ProductScroller
      ref={ref}
      title={title || recommendations?.displayMessage}
      products={recommendations.recs}
      isLoading={isLoading}
      productTileProps={(product: RecommendedProduct) => ({
        onClick: () => {
          sendClickReco(
            {
              recommenderName: recommendations.recommenderName,
              __recoUUID: recommendations.recoUUID,
            },
            product,
          );
        },
        enableFavourite: true,
        isFavourite: wishlist?.customerProductListItems?.some(
          (item: { productId?: string }) => item.productId === product?.productId,
        ),
        onFavouriteToggle: (toBeFavourite: boolean) => {
          const action = toBeFavourite ? addItemToWishlist : removeItemFromWishlist;
          return action(product);
        },
      })}
      {...props}
    />
  );
};

export default RecommendedProducts;

/**
 * Maps one Recently Viewed recommendation onto the subset of `ZimmProductCard` props the
 * `recentlyViewed` variation (SFCC-83) actually renders.
 *
 * Input is exactly what `use-einstein.js`'s `fetchRecProductDetails` produces (search that name
 * in `node_modules/@salesforce/retail-react-app/app/hooks/use-einstein.js`): an Einstein rec
 * merged with its matching Commerce API product, fetched via `getProducts` with `expand:
 * ['availability', 'links', 'promotions', 'options', 'images', 'prices', 'variations']` —
 * `{...rec, ...product, productId: rec.id, image: {disBaseLink: rec.imageUrl, alt:
 * rec.productName}}`.
 *
 * Modelled on `overrides/app/pages/product-detail/productInfo.ts` — no React/react-intl import,
 * `formatPrice` injected as a parameter so this module stays independently testable — and on the
 * general shape of `liveProductCardDemoMapper.ts` (`feature/zimmproductcard-live-demo`, not this
 * branch — read for its approach, not imported). Unlike that demo mapper, this is a production
 * path: real `commerce-sdk-isomorphic` SDK types are used wherever they exist (AGENTS.md > Type
 * Definitions), and only the two fields the SDK doesn't export (`productId`, the flat Einstein
 * `image`) are hand-rolled, each with its own why-comment below.
 *
 * Deliberately narrow scope, stated here rather than left as a silent gap: this mapper only ever
 * returns `currentPrice` (an active selling price). It does not attempt was/now sale-price
 * detection (`originalPrice`) — that needs `getPriceData`-style pricebook logic
 * (`productInfo.ts`'s own `PdpSourcePrice`) that this merged Einstein shape has no equivalent of,
 * and the `recentlyViewed` variation renders no price at all today (see
 * `zimmProductCard/index.tsx`'s `recentlyViewed` `VARIATION_CONFIG` row — `showContent: false`).
 * Mapping `currentPrice` anyway costs nothing and means a future consumer of this same mapper
 * (e.g. a variation that does render price) isn't blocked on this file being revisited.
 */
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type { ZimmProductCardBaseProps, ZimmProductCardImage } from '../components/ui-kits/organisms/zimmProductCard';

/**
 * The real Commerce API `Product` (`commerce-sdk-isomorphic`'s own `ShopperProductsTypes.Product`
 * — not hand-rolled), plus the two fields `fetchRecProductDetails` bolts on that have no SDK
 * equivalent:
 */
export type RecentlyViewedProduct = ShopperProductsTypes.Product & {
  /** Set by `fetchRecProductDetails` to `rec.id`. Guaranteed present and equal to `Product.id`
   *  for every entry that function produces (it already filters out any rec with no matching
   *  product before this shape exists at all) — read this rather than `.id` only because it's
   *  the field the real runtime hook explicitly produces this way. */
  productId: string;
  /** The same function's own quick single-reference image (Einstein's own `rec.imageUrl`/
   *  `rec.productName`), distinct from the full product's own `imageGroups` array below — used
   *  as a fallback only when `imageGroups` filtering comes up empty. See `selectPrimaryImage`. */
  image?: { disBaseLink?: string; alt?: string };
};

/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl,
 *  mirroring `productInfo.ts`'s own `FormatPrice` shape. */
export type FormatPrice = (amount: number, currency: string) => string;

/**
 * The subset of `ZimmProductCardBaseProps` this mapper populates. Deliberately excludes
 * `headingLevel` and `variation` — both are render-context decisions belonging to the container
 * step that maps recs through this mapper and renders the rail (SFCC-83's A6 step), which supplies
 * `headingLevel` uniformly for every card and adds `variation: 'recentlyViewed'` itself when
 * spreading this output into `<ZimmProductCard>` — the rail organism itself (A5) takes already-full
 * `ZimmProductCardProps` objects, so variation must already be set before it sees them. A pure data
 * mapper choosing a heading level would conflate a data concern with a layout one. Also excludes `hoverImage`/`images` — this
 * mapper only ever returns one image (`primaryImage`); see `selectPrimaryImage`'s own docblock
 * for why.
 */
export type RecentlyViewedCard = Pick<
  ZimmProductCardBaseProps,
  'id' | 'href' | 'name' | 'primaryImage' | 'currentPrice'
>;

/** The correctly-sized product image view, per AGENTS.md's image-sizing guidance: never serve an
 *  arbitrary-sized image at thumbnail size. Named rather than inlined per conventions.md's
 *  no-magic-strings rule — this is a real, semantic SFCC image `viewType` key. */
const MEDIUM_VIEW_TYPE = 'medium';

/**
 * Resolves the one image this mapper ever returns. `hoverImage`/`images` are never populated —
 * SFCC-83 AC 3 asks for "the product's index image" (singular), and the `recentlyViewed`
 * variation renders neither a hover-swap nor a gallery (see `zimmProductCard/index.tsx`'s
 * `recentlyViewed` row: `showHoverImageSwap: false`, and its render branch never forwards
 * `images` at all).
 *
 * Prefers `filterImageGroups` at `viewType: 'medium'` (a real, correctly-sized product image) —
 * `variationValues` is deliberately empty: a Recently Viewed rec is already one specific product,
 * not a search hit needing a variant pick the way `liveProductCardDemoMapper.ts`'s own
 * `resolveDemoVariant` handles, so that logic does not apply here. Falls back to Einstein's own
 * flat `image` field only when that filtering produces nothing usable — see
 * `RecentlyViewedProduct.image`'s own comment for what that field is.
 *
 * @returns `null` when neither source has a usable `src`. `ZimmProductCardMediaImage.alt` is
 *   required and non-empty, so there is no safe placeholder card to build without a real image —
 *   a card with an invented placeholder `src` would need an asset this codebase has no confirmed
 *   token or precedent for, so "no usable image" is treated the same as "no usable name" in
 *   `selectRecentlyViewedCard` below: a hard gate that yields no card at all. Returning `null`
 *   here is the only option that structurally cannot violate the non-empty-`alt` contract, since
 *   there is no returned object for `alt` to be empty on.
 */
const selectPrimaryImage = (product: RecentlyViewedProduct, productName: string): ZimmProductCardImage | null => {
  const filteredGroups = filterImageGroups(product.imageGroups ?? [], {
    viewType: MEDIUM_VIEW_TYPE,
    variationValues: {},
  }) as ShopperProductsTypes.ImageGroup[];
  const [groupImage] = filteredGroups[0]?.images ?? [];

  const src = groupImage ? groupImage.disBaseLink || groupImage.link : product.image?.disBaseLink;
  if (!src) return null;

  // ZimmProductCardMediaImage.alt is required and non-empty (unlike base ProductTile's
  // decorative alt: '' convention) — mirrors liveProductCardDemoMapper.ts's own fallback exactly.
  const alt = (groupImage ? groupImage.alt : product.image?.alt)?.trim() || productName;
  return { src, alt };
};

/**
 * @param product - The merged Einstein rec + Commerce API product `fetchRecProductDetails`
 *   produces, or `undefined`/`null` while that data is not yet available.
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the `recentlyViewed` `ZimmProductCard` variation, or `null` when the rec has
 *   no usable name or no usable image — never a broken card, never a throw.
 */
export const selectRecentlyViewedCard = (
  product: RecentlyViewedProduct | undefined | null,
  formatPrice: FormatPrice,
): RecentlyViewedCard | null => {
  if (!product?.name) return null;

  const primaryImage = selectPrimaryImage(product, product.name);
  if (!primaryImage) return null;

  return {
    // Reads productId, not the SDK Product's own `id` — see RecentlyViewedProduct.productId's
    // own comment for why (guaranteed equal in practice, but productId is the field the real
    // runtime hook explicitly produces this way).
    id: product.productId,
    href: productUrlBuilder({ id: product.productId }),
    name: product.name,
    primaryImage,
    // No hardcoded fallback currency — if either is absent, skip formatting rather than guess,
    // matching productInfo.ts's own "no hardcoded fallback currency" comment.
    currentPrice:
      typeof product.price === 'number' && product.currency ? formatPrice(product.price, product.currency) : undefined,
  };
};

