vi.mock('@salesforce/retail-react-app/app/utils/config-utils', () => ({
  getCommerceAgentConfig: () => ({ enableAgentFromHeader: 'false' }),
}));

const renderHeader = (props: { onLogoClick?: () => void; onMenuClick?: () => void; children?: React.ReactNode } = {}) =>
  render(
    // Supplying the one message Header's logo button actually formats avoids react-intl's
    // MISSING_TRANSLATION console warning (harmless — it falls back to defaultMessage either
    // way — but noisy across every test in this file).
    <IntlProvider locale="en-AU" messages={{ 'header.button.assistive_msg.logo': 'Logo' }}>
      <ChakraProvider theme={theme}>
        <Header {...props} />
      </ChakraProvider>
    </IntlProvider>,
  );

// Scoped to Header's own logo contract (SFCC-747) — not a re-test of ZimmLogo's own markup
// (covered by ui-kits/atoms/zimmLogo/index.stories.tsx) or of LeftBar/RightBar (mocked above).
describe('Header logo', () => {
  test('renders the logo as an accessible, natively-focusable button', () => {
    renderHeader();
    const logoButton = screen.getByRole('button', { name: 'Logo' });
    expect(logoButton).toBeInTheDocument();
    expect(logoButton.tagName).toBe('BUTTON');
  });

  test('is reachable via keyboard Tab order', async () => {
    const user = userEvent.setup();
    renderHeader();
    // The topBar row's own controls (LeftBar's menu-control button, RightBar's close-icon
    // stub — see the mocks above) sit ahead of the logoBar's logo button in DOM order; tab
    // past both first, matching the real component tree.
    await user.tab();
    await user.tab();
    await user.tab();
    expect(screen.getByRole('button', { name: 'Logo' })).toHaveFocus();
  });

  test('invokes onLogoClick when clicked, wiring the homepage-navigation handler', async () => {
    const user = userEvent.setup();
    const onLogoClick = vi.fn();
    renderHeader({ onLogoClick });
    await user.click(screen.getByRole('button', { name: 'Logo' }));
    expect(onLogoClick).toHaveBeenCalledTimes(1);
  });
});

// SFCC-884 follow-up — Header derives RightBar's hasWishlistItems from SFCC's native
// wish_list customer product list (base useWishList hook), not a hardcoded placeholder.
// RightBar itself is mocked above; this only asserts Header's own derivation/wiring.
describe('Header wishlist state', () => {
  afterEach(() => {
    mockUseWishList.mockReturnValue({ data: undefined } as ReturnType<typeof useWishList>);
  });

  test('passes hasWishlistItems=false when the wishlist has no items (including guests, who have no list at all)', () => {
    mockUseWishList.mockReturnValue({ data: undefined } as ReturnType<typeof useWishList>);
    renderHeader();

    expect(screen.getByTestId('right-bar-stub')).toHaveAttribute('data-has-wishlist-items', 'false');
  });

  test('passes hasWishlistItems=true when the wish_list product list has at least one item', () => {
    mockUseWishList.mockReturnValue({
      data: { customerProductListItems: [{ id: 'item-1' }] },
    } as unknown as ReturnType<typeof useWishList>);
    renderHeader();

    expect(screen.getByTestId('right-bar-stub')).toHaveAttribute('data-has-wishlist-items', 'true');
  });
});

// A stand-in for the real ListMenu — reports a mega-menu open via the same
// useMegaMenuOpenReporter() hook, rendered through Header's `children` prop (mirrors how base
// _app.jsx actually passes ListMenu — see header/index.tsx's own comment).
const ReportOpenButton = () => {
  const { reportOpen, reportClose } = useMegaMenuOpenReporter();
  return (
    <button type="button" onClick={() => reportOpen(reportClose)}>
      report-open
    </button>
  );
};

// SFCC-96: the desktop/tablet mega-menu open state lifted into the header shell (see
// header/index.tsx's MegaMenuOpenContext.Provider + topBar onMouseLeave).
describe('Header mega-menu open state', () => {
  test('starts closed', () => {
    renderHeader();
    expect(screen.getByTestId('right-bar-stub')).toHaveAttribute('data-menu-expanded', 'closed');
  });

  test('a mega-menu item reporting open swaps RightBar to fullSwap', async () => {
    const user = userEvent.setup();
    renderHeader({ children: <ReportOpenButton /> });

    await user.click(screen.getByRole('button', { name: 'report-open' }));

    expect(screen.getByTestId('right-bar-stub')).toHaveAttribute('data-menu-expanded', 'fullSwap');
  });

  test('clicking the fullSwap Close control closes the mega menu', async () => {
    const user = userEvent.setup();
    renderHeader({ children: <ReportOpenButton /> });
    await user.click(screen.getByRole('button', { name: 'report-open' }));

    await user.click(screen.getByRole('button', { name: 'close-click' }));

    expect(screen.getByTestId('right-bar-stub')).toHaveAttribute('data-menu-expanded', 'closed');
  });
});

// SFCC-97: Header owns the mobile L1/L2 drawer depth state (useHeaderMenuExpandedState) and
// derives menuExpanded for LeftBar/RightBar — this suite is Header's own wiring contract, not
// a re-test of useHeaderMenuExpandedState's internals (covered by that hook's own logic being
// simple enough to exercise entirely through this integration) or of LeftBar/RightBar's
// per-state rendering (already covered by their own suites).
describe('Header mobile drawer state (SFCC-97)', () => {
  test('closed by default: both bars start at menuExpanded="closed"', () => {
    renderHeader();

    expect(screen.getByTestId('left-bar-stub')).toHaveAttribute('data-menu-expanded', 'closed');
    expect(screen.getByTestId('right-bar-stub')).toHaveAttribute('data-menu-expanded', 'closed');
  });

  test("menu-click from closed calls the real onMenuClick (base _app's onOpen) and moves both bars to mobileL1", async () => {
    const user = userEvent.setup();
    const onMenuClick = vi.fn();
    renderHeader({ onMenuClick });

    await user.click(screen.getByRole('button', { name: 'menu-or-back-click' }));

    expect(onMenuClick).toHaveBeenCalledTimes(1);
    expect(screen.getByTestId('left-bar-stub')).toHaveAttribute('data-menu-expanded', 'mobileL1');
    expect(screen.getByTestId('right-bar-stub')).toHaveAttribute('data-menu-expanded', 'mobileL1');
  });

  test('menu-click again from mobileL1 (toggle semantics) calls the registered close handler and resets to closed, without re-calling the real onMenuClick', async () => {
    const user = userEvent.setup();
    const onMenuClick = vi.fn();
    renderHeader({ onMenuClick });

    await user.click(screen.getByRole('button', { name: 'menu-or-back-click' })); // closed -> mobileL1
    await user.click(screen.getByRole('button', { name: 'menu-or-back-click' })); // mobileL1 -> closed

    // No registered close handler in this test (no DrawerMenu mounted under children), so
    // resetting to closed is the only observable effect — the real onMenuClick (onOpen) must
    // not fire a second time, since onOpen cannot toggle.
    expect(onMenuClick).toHaveBeenCalledTimes(1);
    expect(screen.getByTestId('left-bar-stub')).toHaveAttribute('data-menu-expanded', 'closed');
  });

  test('close-click from RightBar resets both bars to closed', async () => {
    const user = userEvent.setup();
    renderHeader();

    await user.click(screen.getByRole('button', { name: 'menu-or-back-click' })); // closed -> mobileL1
    await user.click(screen.getByRole('button', { name: 'close-click' }));

    expect(screen.getByTestId('left-bar-stub')).toHaveAttribute('data-menu-expanded', 'closed');
    expect(screen.getByTestId('right-bar-stub')).toHaveAttribute('data-menu-expanded', 'closed');
  });

  test('drilling in via the shared DrawerMenuStateContext moves both bars to mobileL2, and back-click returns to mobileL1 without closing', async () => {
    const user = userEvent.setup();
    // A minimal stand-in for the real DrawerMenu container — reads the same
    // DrawerMenuStateContext Header provides around `children` and exposes a button to call
    // `drillInto`, so this test can reach mobileL2 the same way the real DrawerMenu does
    // (tapping an L1 row), without needing DrawerMenu's own full render tree here.
    const DrillTrigger = () => {
      const { drillInto } = useDrawerMenuState();
      return (
        <button
          onClick={() =>
            drillInto({
              sys: { id: 'clothing', contentType: { sys: { id: 'headerNavItem' } } },
              fields: { label: 'Clothing' },
            })
          }
        >
          drill-click
        </button>
      );
    };

    renderHeader({ children: <DrillTrigger /> });

    await user.click(screen.getByRole('button', { name: 'menu-or-back-click' })); // closed -> mobileL1
    await user.click(screen.getByRole('button', { name: 'drill-click' })); // mobileL1 -> mobileL2

    expect(screen.getByTestId('left-bar-stub')).toHaveAttribute('data-menu-expanded', 'mobileL2');
    expect(screen.getByTestId('right-bar-stub')).toHaveAttribute('data-menu-expanded', 'mobileL2');

    await user.click(screen.getByRole('button', { name: 'menu-or-back-click' })); // mobileL2 -> mobileL1 (same button, onBack now)

    expect(screen.getByTestId('left-bar-stub')).toHaveAttribute('data-menu-expanded', 'mobileL1');
  });
});

import React from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { renderHook, type RenderHookOptions } from '@testing-library/react';

/**
 * Builds a fresh QueryClient per call — test isolation, no cache bleed between tests.
 * Matches `_app-config/index.tsx`'s real `defaultOptions` for retry/refetchOnWindowFocus so a
 * hook under test behaves the same as it does in the running app.
 */
const createTestQueryClient = () =>
  new QueryClient({
    defaultOptions: {
      queries: { retry: false, refetchOnWindowFocus: false },
    },
  });

/**
 * Renders a hook that calls `@tanstack/react-query`'s `useQuery` inside a fresh
 * `QueryClientProvider` — the same wrapper `_app-config`'s `withReactQuery(AppConfig, ...)`
 * mounts for every page in the real app, so a hook under test needs no provider of its own
 * beyond this. See `.claude/rules/testing.md` > Commerce SDK hooks for the equivalent
 * `renderWithProviders` pattern this mirrors for `CommerceApiProvider`-dependent hooks.
 *
 * @param callback the hook to render
 * @param options `renderHook` options other than `wrapper`, which this helper supplies
 * @returns the same result `@testing-library/react`'s `renderHook` returns
 */
export const renderHookWithQueryClient = <TResult, TProps>(
  callback: (props: TProps) => TResult,
  options?: Omit<RenderHookOptions<TProps>, 'wrapper'>,
) => {
  const queryClient = createTestQueryClient();
  return renderHook(callback, {
    ...options,
    wrapper: ({ children }) => <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>,
  });
};

