8	/*
9	 * Copy-first port of
10	 * node_modules/@salesforce/retail-react-app/app/components/recommended-products/index.jsx
11	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
12	 *
13	 * The differences from the base file are the TypeScript annotations below and house
14	 * formatting — no changed JSX, hook calls, prop names, or reordered `useEffect`s, and the base
15	 * file's own dead check (`recommendations.length < 1` on what is always an object) is ported
16	 * byte-identical in behaviour. The annotations: a `RecommendedProductsProps` type replacing the
17	 * `propTypes` block; a narrow local `RecommendedProduct` type for the one field read off a
18	 * recommendation-context product (reused for the `productTileProps` callback's own `product`
19	 * param below, since it is that same recommendation-context product); an explicit `boolean`
20	 * param on the one nested callback that isn't contextually typed; and inline
21	 * `{ productId?: string }` / `{ id?: string }` object-type-literal params on four
22	 * `.find`/`.some`/`.map` callbacks whose containing expression is untyped (`any`) and therefore
23	 * supplies no contextual parameter type — `noImplicitAny` flags these regardless of the `any`
24	 * receiver (confirmed against `npx tsc --noEmit`, which is why these four are annotated despite
25	 * this file's own initial plan expecting two of them not to need it). The `{ productId?: string
26	 * }` shape and inline-annotation style mirrors the existing precedent at
27	 * product-detail/index.tsx:437 and :735; the `{ id?: string }` shape matches the field the base
28	 * hook itself reads, `use-einstein.js`'s own `reco.recs?.map((rec) => rec.id)` (line 466).
29	 *
30	 * A sixth adjustment, found by lint rather than tsc: the base file destructures `formatMessage`
31	 * straight off `useIntl()`, but `@typescript-eslint/unbound-method` flags any destructured
32	 * reference to it — `formatMessage` is declared with method-shorthand syntax in
33	 * `@formatjs/intl/src/types.d.ts:64-65`, which this rule always flags regardless of whether the
34	 * real implementation needs `this`. Fix: keep the whole object (`const intl = useIntl();`) and
35	 * call `intl.formatMessage(...)` at each of its five call sites instead of destructuring — a
36	 * property-access call sidesteps the rule entirely, with zero behavioural change. Same
37	 * "toolchain requires a different access shape than the untyped base file used" reasoning as the
38	 * annotations above.
39	 *
40	 * SFCC-83/84 build plan step A6 (2026-09-07) adds one branch: when `recommender ===
41	 * EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED` (`'viewed-recently-einstein'`, the same string
42	 * `CART_RECENTLY_VIEWED` resolves to — confirmed identical in
43	 * node_modules/@salesforce/retail-react-app/app/constants.js:154-160), `recommendations.recs`
44	 * maps through `selectRecentlyViewedCard` (overrides/app/utils/recentlyViewedCard.ts) and renders
45	 * `ZimmRecentlyViewedRail` instead, gated by `useRecentlyViewedGate`
46	 * (overrides/app/hooks/useRecentlyViewedGate.ts). Every other recommender keeps the original
47	 * `ProductScroller` branch below, untouched.
48	 *
49	 * `ref` is still attached on the Recently Viewed branch too, via a plain wrapping `<Box
50	 * ref={ref}>` — `isOnScreen` below (the impression-tracking gate for `sendViewReco`/
51	 * `dataCloud.sendViewRecommendations`) only works once `ref.current` is a real DOM node
52	 * (use-intersection-observer.js: `if (!ref?.current) return`, with no dependency on which
53	 * component produced that node), and `ZimmRecentlyViewedRail` is a plain function component with
54	 * no `forwardRef` support of its own. Wrapping here, rather than adding `forwardRef` to that
55	 * already-committed component (A5), keeps this fix entirely inside this file.
56	 *
57	 * `headingLevel`/`variation` are added here, not by the mapper: `selectRecentlyViewedCard`'s own
58	 * docblock states both are deliberately excluded from its output because they are this
59	 * container's decision to make. `headingLevel: 'h3'` is inert for this variation —
60	 * `ZimmProductCardContent` never mounts when `variation: 'recentlyViewed'`
61	 * (zimmProductCard/index.tsx's `VARIATION_CONFIG.showContent`) — and matches the one other
62	 * established value for this same required field (product-list/productListCardMapper.ts).
63	 *
64	 * KNOWN GAP, flagged rather than silently resolved: this branch does not forward this
65	 * component's own `...props` (e.g. PDP's `mx={{base: -4, md: -8, lg: 0}}` on its Recently Viewed
66	 * instance, product-detail/index.tsx) to the `<Box>` wrapper, unlike the ProductScroller branch
67	 * below, which still receives `{...props}` unchanged. `zimmRecentlyViewedRail.css.ts`'s own
68	 * docblock ("GROUP HAS ZERO GAP / ZERO HORIZONTAL PADDING") explicitly defers confirming its
69	 * zero-inset assumption to "once this rail sits inside a real page (A6)" — this step does not
70	 * resolve that either way, and `props` is typed here as `Record<string, unknown>` (this file's
71	 * own index signature), not safely spreadable onto `Box`'s typed props without a cast. Left for
72	 * Marcel to confirm live rather than guessed at.
73	 */
74	
75	import React, { useEffect, useRef, useState } from 'react';
76	import type { ReactNode } from 'react';
77	import { useIntl } from 'react-intl';
78	import { Box, Button } from '@salesforce/retail-react-app/app/components/shared/ui';
79	import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';
80	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
81	import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
82	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
83	import useIntersectionObserver from '@salesforce/retail-react-app/app/hooks/use-intersection-observer';
84	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
85	
86	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
87	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
88	import {
89	  API_ERROR_MESSAGE,
90	  EINSTEIN_RECOMMENDERS,
91	  TOAST_ACTION_VIEW_WISHLIST,
92	  TOAST_MESSAGE_ADDED_TO_WISHLIST,
93	  TOAST_MESSAGE_REMOVED_FROM_WISHLIST,
94	} from '@salesforce/retail-react-app/app/constants';
95	import { useShopperCustomersMutation } from '@salesforce/commerce-sdk-react';
96	// Relative, not the base package path — .claude/rules/overrideStyling.md's "Importing an
97	// already-overridden component from a new component": .storybook/main.js and vitest.config.ts
98	// don't load the overrides resolver, so a base-path import here would silently story/test the
99	// unstyled base component instead of this override.
100	import { ZimmRecentlyViewedRail } from '../ui-kits/organisms/zimmRecentlyViewedRail';
101	import type { ZimmProductCardProps } from '../ui-kits/organisms/zimmProductCard';
102	import { selectRecentlyViewedCard } from '../../utils/recentlyViewedCard';
103	import type { RecentlyViewedProduct } from '../../utils/recentlyViewedCard';
104	import { useRecentlyViewedGate } from '../../hooks/useRecentlyViewedGate';
105	
106	/**
107	 * The one field this file reads off a recommendation-context product. A real
108	 * commerce-sdk-isomorphic Product shape underlies it, but @salesforce/retail-react-app's
109	 * useEinstein/ProductScroller ship untyped (vendor.d.ts's wildcard), so this is narrowed
110	 * to exactly the field touched here rather than invented more broadly (AGENTS.md > Type
111	 * Definitions: hand-roll only the genuinely unexported shape actually used).
112	 */
113	type RecommendedProduct = { productId?: string };
114	
115	export type RecommendedProductsProps = {
116	  /* The title to appear above the product scroller */
117	  title?: ReactNode;
118	
119	  /* The zone to request */
120	  zone?: string;
121	
122	  /* The recommender to request */
123	  recommender?: string;
124	
125	  /* The products to use for recommendation context */
126	  products?: readonly Record<string, unknown>[];
127	
128	  /* Callback to determine if the component should fetch results */
129	  shouldFetch?: () => boolean;
130	
131	  // Index signature for the `...props` passthrough to ProductScroller (itself untyped — see
132	  // vendor.d.ts). Without it, the destructured rest types as `{}` instead of accepting arbitrary
133	  // passthrough, which is the base file's actual intent: forwarding whatever else the caller
134	  // passes.
135	  [key: string]: unknown;
136	};
137	
138	/**
139	 * A component for fetching and rendering product recommendations from the Einstein API
140	 * by a zone or a recommender name.
141	 */
142	const RecommendedProducts = ({
143	  zone,
144	  recommender,
145	  products,
146	  title,
147	  shouldFetch,
148	  ...props
149	}: RecommendedProductsProps) => {
150	  const { isLoading, recommendations, getZoneRecommendations, getRecommendations, sendClickReco, sendViewReco } =
151	    useEinstein();
152	  const { data: customer } = useCurrentCustomer();
153	  const { customerId } = customer;
154	  const { data: wishlist } = useWishList();
155	  const dataCloud = useDataCloud();
156	
157	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
158	  const deleteCustomerProductListItem = useShopperCustomersMutation('deleteCustomerProductListItem');
159	  const toast = useToast();
160	  const navigate = useNavigation();
161	  const intl = useIntl();
162	  // Same split product-list/productListCardMapper.ts's own consumer uses
163	  // (product-list/index.tsx): passed into the mapper rather than formatted there, keeping that
164	  // mapper free of any react-intl dependency of its own.
165	  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });
166	
167	  const ref = useRef();
168	  const isOnScreen = useIntersectionObserver(ref, { useOnce: true });
169	  const [_products, setProducts] = useState(products);
170	  // Unconditional, alongside the hook calls above — must run on every render, including the
171	  // ones that hit the dead-code early return two blocks below, per React's rules of hooks.
172	  const hasRecentlyViewed = useRecentlyViewedGate();
173	
174	  useEffect(() => {
175	    // Check if the component should fetch results or not. This is useful
176	    // when you are still waiting on additional data, like `products`.
177	    if (typeof shouldFetch === 'function' && !shouldFetch()) {
178	      return;
179	    }
180	
181	    // Fetch either zone or recommender, but not both. If a zone and recommender
182	    // name are both provided, `zone` takes precendence.
183	    if (zone) {
184	      getZoneRecommendations(zone, _products);
185	      return;
186	    }
187	    if (recommender) {
188	      getRecommendations(recommender, _products);
189	      return;
190	    }
191	  }, [zone, recommender, _products]);
192	
193	  useEffect(() => {
194	    // This is an optimization that eliminates superfluous rerenders/fetching by
195	    // keeping a copy of the `products` array prop in state for shallow comparison.
196	    if (!Array.isArray(products)) {
197	      return;
198	    }
199	    if (products.length !== _products?.length || !products.every((val, index) => val === _products?.[index])) {
200	      setProducts(products);
201	    }
202	  }, [products]);
203	
204	  useEffect(() => {
205	    if (isOnScreen && recommendations?.recs) {
206	      sendViewReco(
207	        {
208	          recommenderName: recommendations.recommenderName,
209	          __recoUUID: recommendations.recoUUID,
210	        },
211	        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
212	      );
213	      dataCloud.sendViewRecommendations(
214	        {
215	          recommenderName: recommendations.recommenderName,
216	          __recoUUID: recommendations.recoUUID,
217	        },
218	        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
219	      );
220	    }
221	  }, [isOnScreen, recommendations]);
222	
223	  // The component should remove itself altogether if it has no recommendations
224	  // and we aren't loading any.
225	  if (!isLoading && (!recommendations || recommendations.length < 1)) {
226	    return null;
227	  }
228	
229	  // TODO: DRY this handler when intl provider is available globally
230	  const addItemToWishlist = async (product: RecommendedProduct) => {
231	    try {
232	      if (!wishlist || !customerId) {
233	        return;
234	      }
235	      await createCustomerProductListItem.mutateAsync({
236	        parameters: {
237	          listId: wishlist.id,
238	          customerId,
239	        },
240	        body: {
241	          quantity: 1,
242	          productId: product.productId,
243	          public: false,
244	          priority: 1,
245	          type: 'product',
246	        },
247	      });
248	
249	      toast({
250	        title: intl.formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
251	        status: 'success',
252	        action: (
253	          // it would be better if we could use <Button as={Link}>
254	          // but unfortunately the Link component is not compatible
255	          // with Chakra Toast, since the ToastManager is rendered via portal
256	          // and the toast doesn't have access to intl provider, which is a
257	          // requirement of the Link component.
258	          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
259	            {intl.formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
260	          </Button>
261	        ),
262	      });
263	    } catch {
264	      toast({
265	        title: intl.formatMessage(API_ERROR_MESSAGE),
266	        status: 'error',
267	      });
268	    }
269	  };
270	
271	  const removeItemFromWishlist = async (product: RecommendedProduct) => {
272	    try {
273	      const wishlistItem = wishlist?.customerProductListItems?.find(
274	        (item: { productId?: string }) => item.productId === product.productId,
275	      );
276	      if (!wishlistItem || !wishlist || !customerId) {
277	        return;
278	      }
279	      await deleteCustomerProductListItem.mutateAsync({
280	        parameters: {
281	          customerId,
282	          itemId: wishlistItem.id,
283	          listId: wishlist.id,
284	        },
285	      });
286	      toast({
287	        title: intl.formatMessage(TOAST_MESSAGE_REMOVED_FROM_WISHLIST),
288	        status: 'success',
289	        id: product.productId,
290	      });
291	    } catch {
292	      toast({
293	        title: intl.formatMessage(API_ERROR_MESSAGE),
294	        status: 'error',
295	      });
296	    }
297	  };
298	
299	  // SFCC-83 — Recently Viewed only. Every other recommender falls through to the unchanged
300	  // ProductScroller branch below.
301	  if (recommender === EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED) {
302	    // AC 8's empty-state gate — see useRecentlyViewedGate.ts's own docblock. No rail, no title,
303	    // no placeholder.
304	    if (!hasRecentlyViewed) {
305	      return null;
306	    }
307	
308	    const cards: ZimmProductCardProps[] = (recommendations?.recs ?? [])
309	      .map((rec: RecentlyViewedProduct) => selectRecentlyViewedCard(rec, formatPrice))
310	      .filter((card): card is NonNullable<typeof card> => card !== null)
311	      .map(
312	        (card): ZimmProductCardProps => ({
313	          ...card,
314	          // Inert for this variation — ZimmProductCardContent never mounts when
315	          // variation: 'recentlyViewed' (zimmProductCard/index.tsx's
316	          // VARIATION_CONFIG.showContent). 'h3' matches the one other established value for
317	          // this same required field (product-list/productListCardMapper.ts).
318	          headingLevel: 'h3',
319	          variation: 'recentlyViewed',
320	        }),
321	      );
322	
323	    return (
324	      // Ref-attachment point only, no styling of its own — see the module docblock's own
325	      // isOnScreen/forwardRef note above for why this wrapper exists at all.
326	      <Box ref={ref}>
327	        <ZimmRecentlyViewedRail title={title || recommendations?.displayMessage} cards={cards} />
328	      </Box>
329	    );
330	  }
331	
332	  return (
333	    <ProductScroller
334	      ref={ref}
335	      title={title || recommendations?.displayMessage}
336	      products={recommendations.recs}
337	      isLoading={isLoading}
338	      productTileProps={(product: RecommendedProduct) => ({
339	        onClick: () => {
340	          sendClickReco(
341	            {
342	              recommenderName: recommendations.recommenderName,
343	              __recoUUID: recommendations.recoUUID,
344	            },
345	            product,
346	          );
347	        },
348	        enableFavourite: true,
349	        isFavourite: wishlist?.customerProductListItems?.some(
350	          (item: { productId?: string }) => item.productId === product?.productId,
351	        ),
352	        onFavouriteToggle: (toBeFavourite: boolean) => {
353	          const action = toBeFavourite ? addItemToWishlist : removeItemFromWishlist;
354	          return action(product);
355	        },
356	      })}
357	      {...props}
358	    />
359	  );
360	};
361	
362	export default RecommendedProducts;
